}
BG = '#fafafa'
GRID = '#e0e0e0'

plt.rcParams.update({
    'font.family': 'DejaVu Sans',
    'axes.facecolor': BG,
    'figure.facecolor': 'white',
    'grid.color': GRID,
    'grid.alpha': 0.6,
})


def fig_to_svg_base64(fig):
    """Convert matplotlib figure to base64 SVG for inline embedding."""
    buf = BytesIO()
    fig.savefig(buf, format='svg', bbox_inches='tight', transparent=False)
    buf.seek(0)
    svg = buf.read().decode('utf-8')
    plt.close(fig)
    return svg


def load_and_clean():
    """Load CSV, clean, parse timestamps, filter to Feb 2026."""
    df = pd.read_csv(CSV_PATH)

    # Remove header-row artifacts
    df = df[df['fuel_type'] != 'fuel_type'].copy()

    # Parse timestamps
    df['recorded_at'] = pd.to_datetime(df['recorded_at'], utc=True)
    df['source_updated_at'] = pd.to_datetime(df['source_updated_at'], utc=True)

    # Compute update lag in hours
    df['update_lag_hours'] = (
        (df['recorded_at'] - df['source_updated_at']).dt.total_seconds() / 3600
    )

    # Price in pounds (for display)
    df['price_gbp'] = df['price_pence'] / 100

    # Filter to February 2026
    feb = df[df['recorded_at'].dt.strftime('%Y-%m') == TARGET_MONTH].copy()

    return df, feb


def compute_price_stats(feb):
    """Compute per-fuel-type price statistics."""
    stats = feb.groupby('fuel_type')['price_pence'].agg([
        'count', 'mean', 'median', 'std', 'min', 'max',
        lambda x: x.quantile(0.25),
        lambda x: x.quantile(0.75),
    ]).round(2)
    stats.columns = ['count', 'mean', 'median', 'std', 'min', 'max', 'q25', 'q75']
    stats['iqr'] = (stats['q75'] - stats['q25']).round(2)
    stats['spread'] = (stats['max'] - stats['min']).round(2)
    stats['mean_gbp'] = (stats['mean'] / 100).round(3)
    stats['median_gbp'] = (stats['median'] / 100).round(3)
    return stats


def compute_update_lag(feb):
    """Compute update lag statistics."""
    lag = feb.groupby('fuel_type')['update_lag_hours'].agg([
        'count', 'mean', 'median', 'std', 'min', 'max',
        lambda x: x.quantile(0.25),
        lambda x: x.quantile(0.75),
        lambda x: (x > 168).sum(),   # > 1 week stale
    ]).round(2)
    lag.columns = ['count', 'mean', 'median', 'std', 'min', 'max', 'q25', 'q75', 'stale_gt_1wk']
    lag['stale_pct'] = (lag['stale_gt_1wk'] / lag['count'] * 100).round(1)
    return lag


# ══════════════════════════════════════════════════════════════════
# CHART GENERATORS
# ══════════════════════════════════════════════════════════════════

def chart_price_boxplot(feb):
    """Box plot of prices by fuel type."""
    fuel_order = ['E10', 'B7_STANDARD', 'E5', 'B7_PREMIUM', 'B10', 'HVO']
    present = [f for f in fuel_order if f in feb['fuel_type'].unique()]

    fig, ax = plt.subplots(figsize=(10, 5.5))
    data = [feb[feb['fuel_type'] == f]['price_pence'].values for f in present]

    bp = ax.boxplot(data, labels=present, patch_artist=True, widths=0.55,
                    medianprops={'color': '#333', 'linewidth': 2},
                    flierprops={'marker': '.', 'markersize': 3, 'alpha': 0.4})

    for patch, fuel in zip(bp['boxes'], present):
        patch.set_facecolor(COLORS.get(fuel, '#888'))
        patch.set_alpha(0.7)

    ax.set_ylabel('Price (pence per litre)', fontweight='bold')
    ax.set_title('Price Distribution by Fuel Type — February 2026', fontweight='bold', fontsize=13)
    ax.grid(axis='y', alpha=0.4)
    ax.set_ylim(bottom=110)

    return fig_to_svg_base64(fig)


def chart_price_violin(feb):
    """Violin plot showing full distribution shape."""
    fuel_order = ['E10', 'B7_STANDARD', 'E5', 'B7_PREMIUM', 'B10', 'HVO']
    present = [f for f in fuel_order if f in feb['fuel_type'].unique()]

    fig, ax = plt.subplots(figsize=(10, 5.5))
    data = [feb[feb['fuel_type'] == f]['price_pence'].values for f in present]

    vp = ax.violinplot(data, positions=range(len(present)), widths=0.7,
                       showmeans=True, showmedians=True)
    for i, body in enumerate(vp['bodies']):
        body.set_facecolor(COLORS.get(present[i], '#888'))
        body.set_alpha(0.65)

    ax.set_xticks(range(len(present)))
    ax.set_xticklabels(present)
    ax.set_ylabel('Price (pence per litre)', fontweight='bold')
    ax.set_title('Price Distribution Shape by Fuel Type — February 2026', fontweight='bold', fontsize=13)
    ax.grid(axis='y', alpha=0.4)

    return fig_to_svg_base64(fig)


def chart_spread_bars(stats):
    """Horizontal bar chart showing price spread and IQR."""
    fuel_order = ['E10', 'B7_STANDARD', 'E5', 'B7_PREMIUM', 'B10', 'HVO']
    present = [f for f in fuel_order if f in stats.index]
    st = stats.loc[present]

    fig, ax = plt.subplots(figsize=(10, 5))

    y_pos = range(len(present))
    heights = 0.35
    ax.barh([y + heights/2 for y in y_pos], st['spread'], heights,
            color=['#d73027' if v > 30 else '#fc8d59' if v > 15 else '#fee090' for v in st['spread']],
            alpha=0.8, label='Max − Min Spread')
    ax.barh([y - heights/2 for y in y_pos], st['iqr'], heights,
            color=['#4575b4' for _ in present], alpha=0.8, label='Interquartile Range (IQR)')

    ax.set_yticks(y_pos)
    ax.set_yticklabels(present)
    ax.set_xlabel('Price range (pence)', fontweight='bold')
    ax.set_title('Price Spread & IQR by Fuel Type — February 2026', fontweight='bold', fontsize=13)
    ax.legend(loc='lower right')
    ax.grid(axis='x', alpha=0.4)

    return fig_to_svg_base64(fig)


def chart_lag_histogram(feb):
    """Histogram of update lag in hours (log scale)."""
    fig, ax = plt.subplots(figsize=(10, 4.5))

    lags = feb['update_lag_hours'].dropna()
