    bins = np.linspace(0, min(lags.max(), 720), 80)
    ax.hist(lags, bins=bins, color='#4575b4', alpha=0.75, edgecolor='white', linewidth=0.3)

    median_lag = lags.median()
    ax.axvline(median_lag, color='#d73027', linestyle='--', linewidth=2,
              label=f'Median: {median_lag:.1f} hours')
    ax.axvline(168, color='#fdae61', linestyle=':', linewidth=1.5,
              label='7-day threshold')

    ax.set_xlabel('Update Lag (hours)', fontweight='bold')
    ax.set_ylabel('Number of records', fontweight='bold')
    ax.set_title('Distribution of Retailer Update Lag — February 2026', fontweight='bold', fontsize=13)
    ax.legend()
    ax.grid(axis='y', alpha=0.4)

    return fig_to_svg_base64(fig)


def chart_lag_by_fuel(lag_stats):
