    ax.grid(axis='y', alpha=0.4)

    return fig_to_svg_base64(fig)


def chart_station_coverage(feb):
    """Stations reporting each fuel type vs. total unique stations."""
    total_stations = feb['node_id'].nunique()
    coverage = feb.groupby('fuel_type')['node_id'].nunique().sort_values(ascending=True)

    fig, ax = plt.subplots(figsize=(9, 5))
