            </thead>
            <tbody>''' + ''.join(f'''
                <tr>
                    <td class="fuel-label" style="background:{COLORS.get(ft,'#888')};color:white;font-weight:bold;text-align:center;">{ft}</td>
                    <td>{cov_counts.get(ft, 0):,}</td>
                    <td>{cov_counts.get(ft, 0) / total_stations * 100:.1f}%</td>
