def fmt_pence(v):
    return f"£{v/100:.2f}" if pd.notna(v) else "N/A"


def build_html(feb, price_stats, lag_stats, charts):
    """Assemble the full HTML report."""
    total_records = len(feb)
    total_stations = feb['node_id'].nunique()
    date_min = feb['recorded_at'].min().strftime('%d %B %Y')
    date_max = feb['recorded_at'].max().strftime('%d %B %Y')
    fuel_types_present = sorted(feb['fuel_type'].unique())

    # KPI cards
    kpi_data = []
    for ft in fuel_types_present:
        s = price_stats.loc[ft]
        kpi_data.append({
            'fuel': ft,
            'mean_gbp': s['mean_gbp'],
            'median_gbp': s['median_gbp'],
            'spread': s['spread'],
            'iqr': s['iqr'],
            'count': int(s['count']),
        })

    # Build KPI table rows
    kpi_rows = ''
    for k in kpi_data:
        kpi_rows += f'''
        <tr>
            <td class="fuel-label" style="background:{COLORS.get(k['fuel'],'#888')};color:white;font-weight:bold;text-align:center;">{k['fuel']}</td>
            <td>{k['count']:,}</td>
            <td>{fmt_pence(k['mean_gbp'] * 100)}</td>
            <td>{fmt_pence(k['median_gbp'] * 100)}</td>
            <td>{k['spread']:.1f}p</td>
            <td>{k['iqr']:.1f}p</td>
            <td>{fmt_pence(price_stats.loc[k['fuel'], 'min'])} – {fmt_pence(price_stats.loc[k['fuel'], 'max'])}</td>
        </tr>'''

    # Update freshness table
    lag_rows = ''
    for ft in fuel_types_present:
        ls = lag_stats.loc[ft]
        lag_rows += f'''
        <tr>
            <td class="fuel-label" style="background:{COLORS.get(ft,'#888')};color:white;font-weight:bold;text-align:center;">{ft}</td>
            <td>{ls['median']:.1f}h</td>
            <td>{ls['mean']:.1f}h</td>
            <td>{ls['q25']:.1f}h – {ls['q75']:.1f}h</td>
            <td>{ls['min']:.1f}h</td>
            <td>{ls['max']:.1f}h</td>
            <td>{ls['stale_gt_1wk']:,} ({ls['stale_pct']:.1f}%)</td>
        </tr>'''

    # Key findings
    # Identify most & least expensive
    most_expensive = price_stats['mean'].idxmax()
    least_expensive = price_stats['mean'].idxmin()
    biggest_spread = price_stats['spread'].idxmax()
    biggest_spread_val = price_stats.loc[biggest_spread, 'spread']
    biggest_iqr = price_stats['iqr'].idxmax()
    biggest_iqr_val = price_stats.loc[biggest_iqr, 'iqr']

    worst_lag_fuel = lag_stats['median'].idxmax()
    worst_lag_val = lag_stats.loc[worst_lag_fuel, 'median']
    best_lag_fuel = lag_stats['median'].idxmin()
    best_lag_val = lag_stats.loc[best_lag_fuel, 'median']
    total_stale = int(lag_stats['stale_gt_1wk'].sum())
    stale_pct_overall = (total_stale / len(feb) * 100)

    # Station coverage details
    cov_counts = feb.groupby('fuel_type')['node_id'].nunique()
    most_covered = cov_counts.idxmax()
    least_covered = cov_counts.idxmin()
    fuel_per_station = feb.groupby('node_id')['fuel_type'].nunique()
    stations_all_four = (fuel_per_station >= len(fuel_types_present)).sum()
    stations_one_only = (fuel_per_station == 1).sum()

    html = f'''<!DOCTYPE html>
