    price_stats = compute_price_stats(feb)
    print(price_stats.to_string())

    print("\nComputing update lag statistics...")
    lag_stats = compute_update_lag(feb)
    print(lag_stats.to_string())

    print("\nGenerating charts...")
    charts = {
        'price_boxplot': chart_price_boxplot(feb),
        'price_violin': chart_price_violin(feb),
        'spread_bars': chart_spread_bars(price_stats),
        'lag_histogram': chart_lag_histogram(feb),
        'lag_by_fuel': chart_lag_by_fuel(lag_stats),
        'station_coverage': chart_station_coverage(feb),
        'fuel_per_station': chart_fuel_types_per_station(feb),
        'price_timeseries': chart_price_timeseries(feb),
    }

    print("\nBuilding HTML report...")
    html = build_html(feb, price_stats, lag_stats, charts)

    Path(OUTPUT_PATH).write_text(html, encoding='utf-8')
    print(f"\nReport saved to: {OUTPUT_PATH}")
    print(f"File size: {len(html):,} bytes")


if __name__ == '__main__':
    main()

#!/usr/bin/env python3
"""UK Retail Fuel Price Trend Analysis — Report Builder"""

import pandas as pd
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.ticker as mticker
from io import BytesIO
import base64
import json
from datetime import datetime
from pathlib import Path

# ── Configuration ─────────────────────────────────────────────────
CSV_PATH = '/app/benchmark/data.csv'
OUTPUT_PATH = '/app/output/final_report.html'
TARGET_MONTH = '2026-02'

# ── Color palette (analytical, professional) ──────────────────────
COLORS = {
    'E10': '#2c7bb6',           # blue
    'B7_STANDARD': '#d7191c',   # red
    'E5': '#fdae61',            # orange
    'B7_PREMIUM': '#5e3c99',    # purple
    'B10': '#1b9e77',           # green
    'HVO': '#a65628',           # brown
}
BG = '#fafafa'
GRID = '#e0e0e0'

plt.rcParams.update({
    'font.family': 'DejaVu Sans',
    'axes.facecolor': BG,
    'figure.facecolor': 'white',
    'grid.color': GRID,
    'grid.alpha': 0.6,
})


def fig_to_svg_base64(fig):
    """Convert matplotlib figure to base64 SVG for inline embedding."""
    buf = BytesIO()
    fig.savefig(buf, format='svg', bbox_inches='tight', transparent=False)
    buf.seek(0)
    svg = buf.read().decode('utf-8')
    plt.close(fig)
    return svg


def load_and_clean():
    """Load CSV, clean, parse timestamps, filter to Feb 2026."""
    df = pd.read_csv(CSV_PATH)

    # Remove header-row artifacts
    df = df[df['fuel_type'] != 'fuel_type'].copy()

    # Parse timestamps
    df['recorded_at'] = pd.to_datetime(df['recorded_at'], utc=True)
    df['source_updated_at'] = pd.to_datetime(df['source_updated_at'], utc=True)

    # Compute update lag in hours
    df['update_lag_hours'] = (
        (df['recorded_at'] - df['source_updated_at']).dt.total_seconds() / 3600
    )

    # Price in pounds (for display)
    df['price_gbp'] = df['price_pence'] / 100

    # Filter to February 2026
    feb = df[df['recorded_at'].dt.strftime('%Y-%m') == TARGET_MONTH].copy()

    return df, feb


def compute_price_stats(feb):
    """Compute per-fuel-type price statistics."""
    stats = feb.groupby('fuel_type')['price_pence'].agg([
        'count', 'mean', 'median', 'std', 'min', 'max',
        lambda x: x.quantile(0.25),
        lambda x: x.quantile(0.75),
    ]).round(2)
    stats.columns = ['count', 'mean', 'median', 'std', 'min', 'max', 'q25', 'q75']
    stats['iqr'] = (stats['q75'] - stats['q25']).round(2)
    stats['spread'] = (stats['max'] - stats['min']).round(2)
    stats['mean_gbp'] = (stats['mean'] / 100).round(3)
    stats['median_gbp'] = (stats['median'] / 100).round(3)
    return stats


def compute_update_lag(feb):
    """Compute update lag statistics."""
    lag = feb.groupby('fuel_type')['update_lag_hours'].agg([
        'count', 'mean', 'median', 'std', 'min', 'max',
        lambda x: x.quantile(0.25),
        lambda x: x.quantile(0.75),
        lambda x: (x > 168).sum(),   # > 1 week stale
    ]).round(2)
    lag.columns = ['count', 'mean', 'median', 'std', 'min', 'max', 'q25', 'q75', 'stale_gt_1wk']
    lag['stale_pct'] = (lag['stale_gt_1wk'] / lag['count'] * 100).round(1)
    return lag


